  `mail_status` int(11) DEFAULT 0 COMMENT '0: Chưa gửi request yêu cầu thanh toán cho hóa đơn\n1: Đã gửi',
  `created_at` datetime DEFAULT NULL COMMENT 'ngày tạo',
  `updated_at` datetime DEFAULT NULL,
  `used_bonus` decimal(10,2) NOT NULL DEFAULT 0.00,
  `paypal_account_id` int(11) NOT NULL DEFAULT 0,
  `paypal_email` varchar(255) NOT NULL,
  `paypal_token` varchar(255) NOT NULL,
  `user_ip` varchar(30) NOT NULL,
  `user_info` varchar(300) NOT NULL,
  `email_die` int(11) NOT NULL DEFAULT 0,
  `stripe_account_id` int(11) NOT NULL,
  `stripe_url` varchar(300) NOT NULL
