INSERT INTO `category_faq` (`id`, `title`, `description`, `seo_title`, `seo_description`, `seo_keyword`, `url_title`, `code`) VALUES
(1, 'Frequently Asked Questions', '<p>Frequently Asked Question</p>\r\n\r\n<ul>\r\n</ul>\r\n', 'Frequently Asked Questions | BuyPremiumKey.Com Reseller', 'We will answer all your questions when shopping at buypremiumkey agent. Buy premium key, premium account, voucher, coupon now to enjoy unprecedented offers.', 'buypremiumkey, faq buypremium, faq buy premium account, premium key, voucher, coupon, voucher paypal, coupon paypal, premium paypal, key paypal', 'frequently-asked-questions', 'FAQ'),
(2, 'How to activate Premium key', '<p>How to Activate Premium Key. Instructs the user to activate the premium key, premium account, voucher, coupon on the file host.</p>\r\n', 'How to activate Premium key, Voucher, Code | Buypremiumkey Reseller', 'How to Activate Premium Key. Instructs the user to activate the premium key, premium account, voucher, coupon on the file host.', 'BigFile Activate, Dep File Activate, Keep2share Activate, DataFile Activate, Fileboom Activate, Rapid Gator Activate, Publish2 Activate, 1fichier Activate, File Joker Activate, Nova File Activate, Deposit Files Activate, EasyBytez Activate, Turbobit Premium Activate, Hitfile Activate, TezFiles Activate, Xubster Activate, File.al Activate, Debriditalia Activate, Filefactory Activate, FilesMonster Activate, Uploaded Activate, Subyshare Activate, IcerBox Activate, Zevera Activate, Prembox Activate, Fistfast Activate, Rockfile Activate, Takefile Activate, Uploadgig Activate, Fireget Activate, Premiumlink generator Activate, Upstore Activate, Alfafile Activate, Nitroflare Activate, UploadBoy Activate, Upload.cd Activate, Lunaticfiles Activate, Ex-load Activate, Real-debrid Activate, Alldebrid Activate, Filespace Activate, DaoFile Activate, Elephantafiles Activate, Filenext Activate', 'how-to-activate-premium-key', 'APK'),
(3, 'My Orders', '<p>My Orders</p>\r\n', 'My orders | Buy premium key at buypremiumkey.com reseller get 2% bonus', 'When you buy any product from buypremiumkey reseller you always get a bonus of 1% to 2%. This money will help you to buy premium key free from us.', 'buy premium key, free premium key, get bonus key, buypremiumkey, buypremiumkey reseller, bonus 2%', 'my-orders', 'MO'),
(4, 'Payment Method', '<p>Payment Method</p>\r\n', 'Buy premium key via paypal, webmoney, perfect money, amazon pay at Buy', 'Buy premium key via paypal, webmoney, perfect money, amazon pay at BuyPremiumKey.com Reseller you will get 2% bonus per order completed. We are committed to sel', 'Buy premium via paypal, buy premium via amazon, buy premium via perfect money, buy premium via amazon', 'payment-method', 'PM');
INSERT INTO `faq` (`id`, `title`, `url_title`, `description`, `seo_title`, `seo_description`, `seo_keyword`, `created_at`, `updated_at`, `category_faq_id`, `view`, `product_id`) VALUES
(1, 'Frequently Asked Questions', 'frequently-asked-questions', '<h2>Why purchase from BuyPremiumKey.Com?</h2>\r\n\r\n<p>Because we are an Official Reseller! We offer you the simplest &amp; fastest way to upgrade your account&nbsp;and professional transactions!</p>\r\n\r\n<h2>Is registration on BuyPremiumKey.Com website requested?</h2>\r\n\r\n<p>No, you can purchase without registration. However, we encourage you to sign up for an account to track your order. The data provided during registration is confidential and shall not be used by any third party.</p>\r\n\r\n<h2>How can I order?</h2>\r\n\r\n<p>On homepage, chose the required product or choose directly the service you are interested,&nbsp;and follow the instructions to complete the payment.</p>\r\n\r\n<h2>What is the lead-time to process my order?</h2>\r\n\r\n<p>After you successfully pay, we will send you the premium key after 2h-8h. If you have not received your key within the above time period, please contact us, we will process it to you immediately. Delayed because we have to handle a lot of orders for other customers. Thank you so much!</p>\r\n\r\n<h2>Why hasn&rsquo;t my order been processed yet?</h2>\r\n\r\n<p>Your order is in process. If your order has not been processed within 8&nbsp;hours after your actual on-line payment, please send us an email so we can verify the status of your order.</p>\r\n\r\n<h2>I didn&#39;t receive my voucher after a payment.</h2>\r\n\r\n<ol>\r\n	<li>Please check your email box, email Spam box, SMS inbox...</li>\r\n	<li>If your order has not been processed within 6 hours after your payment, please <a href=\"http://buypremiumkey.com/users/contact-us\">contact us</a></li>\r\n</ol>\r\n\r\n<h2>Is my credit/debit card information secure? Where is it kept?</h2>\r\n\r\n<ol>\r\n	<li>Your information is securely stored and encrypted by Payment Gateway, whom handle billions in payments.</li>\r\n	<li>Credit card details will be handled securely to ensure confidentiality and that 256 bit SSL encryption is employed to ensure sensitive data is protected during transmission over the internet.</li>\r\n</ol>\r\n', 'Frequently Asked Questions | BuyPremiumKey.Com Reseller', 'We will answer all your questions when shopping at buypremiumkey agent. Buy premium key, premium account, voucher, coupon now to enjoy unprecedented offers.', 'buypremiumkey, faq buypremium, faq buy premium account, premium key, voucher, coupon, voucher paypal, coupon paypal, premium paypal, key paypal', '2018-05-17 03:09:07', '2018-10-07 18:33:55', 1, 381, 0),
(2, 'Cancel an Order', 'cancel-an-order', '<h2>If you want to cancel the completed order.</h2>\r\n\r\n<p>No, you can. We dont offer refund for completed order, but if you didnt use service we can refund your order, but you must be taken a little for processing fee 5% + refund fee 5%. And we must resell or remove your service before we refund your order.</p>\r\n\r\n<h2>If you want to cancel the processing order, we have 3&nbsp;cases:</h2>\r\n\r\n<p><strong>That order is pending to process and&nbsp;you have not pay yet</strong></p>\r\n\r\n<p>You can cancel the order by login then go to order history and select your order. Here you cancel the order by clicking the Cancel button&nbsp;as shown below</p>\r\n\r\n<p><img alt=\"Cancel order at buypremiumkey\" src=\"http://buypremiumkey.com/images/news/1526529284.png\" style=\"width:100%\" /></p>\r\n\r\n<p>Note:&nbsp;If you are an anonymous user, when you place your first order, we always send your login information along with your order information via email.</p>\r\n\r\n<p><strong>You paid but we have not sent you a premium&nbsp;key yet</strong></p>\r\n\r\n<p>In this case, please <a href=\"http://buypremiumkey.com/users/contact-us\">contact us</a>, we will process your request via email.</p>\r\n\r\n<p><strong>That order is processed, same completed order case, please read above.</strong></p>\r\n\r\n<p><strong>Note: If you dont want to pay, please do not pay. Because when you order is completed, we dont offer full refund except special case was stated in&nbsp;<a href=\"http://buypremiumkey.com/information-view-5/terms-condition.html\">Refund policy</a></strong></p>\r\n\r\n<p>We offer 100% guarantee. However, our products are subject to Terms and Conditions and we will offer a refund only if the service did not work.</p>\r\n\r\n<p>Our overall objective is safety and execution of obligations to clients. On the other hand we try to protect ourselves from casual the incidents connected with a piracy and swindle concerning the software.</p>\r\n\r\n<p>As we sell non-tangible irrevocable goods we do not issue refunds once the order is accomplished and the product is delivered. As a customer you are responsible for understanding this upon purchasing any item at our site.</p>\r\n\r\n<p>If the error occur we will try our best to solve the problem in 72 hours after this time if the problem can&#39;t be solved we will make the refund but the money will be deducted the payment fee It is dependent on the payment gateway fee, usually it is range from 1% to 3% product value.</p>\r\n\r\n<p>We do not take responsibility and no warranty if your account is banned, blocked because of broken the rules of File-hosting company.</p>\r\n', 'Cancel an Order | BuyPremiumKey.Com Reseller', 'You can cancel the order by login then go to order history and select your order. Here you cancel the order by clicking the Cancel button. BuyPremiumKey.Com', 'cancel order, cancel premium key, buy premium key, buypremiumkey reseller, buy premium account, buy premium via paypal, premium paypal, key paypal', '2018-05-17 04:09:09', '2019-08-27 10:24:18', 1, 261, 0),
(3, 'Login and Password help', 'login-and-password-help', '<p>If you&nbsp;<strong>do not&nbsp;remember</strong>&nbsp;your password, you can request a new password by confirming your identity.</p>\r\n\r\n<ol>\r\n	<li>Go to&nbsp;<a href=\"http://buypremiumkey.com/users/login\"><strong>Login</strong>&nbsp;</a>on menu.</li>\r\n	<li>And choose&nbsp;<a href=\"http://buypremiumkey.com/users/forgotten\"><strong>Forgotten Password</strong></a>.</li>\r\n	<li>Fill your email here.</li>\r\n	<li>Then you will recieve a confirmation from us to your email.</li>\r\n	<li>Click on that link, you can set your new password.</li>\r\n</ol>\r\n\r\n<p><img alt=\"Forgot password buypremiumkey reseller\" src=\"http://buypremiumkey.com/images/news/1526713162.PNG\" style=\"width:100%\" /></p>\r\n\r\n<p>If you&nbsp;<strong>remember&nbsp;</strong>your current password, you can change it from your My Account.</p>\r\n\r\n<ol>\r\n	<li>Login to your account.</li>\r\n	<li>Go to&nbsp;<strong>My Account</strong>&nbsp;on the menu.</li>\r\n	<li>Choose&nbsp;<strong>Change your password</strong>.</li>\r\n	<li>Then you can change your password here.</li>\r\n</ol>\r\n\r\n<p><img alt=\"Change password buypremiumkey reseller\" src=\"http://buypremiumkey.com/images/news/1526713298.PNG\" style=\"width:100%\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n', 'Login and Password help | Buy Premium Key Reseller', 'BuyPremiumKey is a reseller of many types of premium keys, account. We always bring you the cheapest products and put the interests of customers on the top', 'buypremiumkey, change password, forgotten password, buy key, buy voucher, buy premium code, key cheapest', '2018-05-19 07:10:15', '2018-10-07 01:26:36', 1, 185, 0),
(4, 'Why was my premium account banned? Help me!', 'why-was-my-premium-account-banned-help-me', '<p>Unfortunately, that is your account, we do not touch on your account so you must keep it safe.</p>\r\n\r\n<p>We are reseller service , we are not the file sharing service, so we cant provide you the exact reason. You should contact to file sharing to get your reason.&nbsp;Show them the details of the problem you are having. What have you done recently? The support team will help you solve the problem.</p>\r\n\r\n<p>But we can provide you some information to prevent banning on your account:</p>\r\n\r\n<ol>\r\n	<li>Do not download more files at the same time. That can be called LEECHER.</li>\r\n	<li>Do not share your account to anyone else.</li>\r\n	<li>Use strong password and put it to safe place.</li>\r\n</ol>\r\n\r\n<p><strong>Best regards</strong></p>\r\n\r\n<p>BuyPremiumKey Reseller</p>\r\n', 'Why was my premium account banned? Help me!', 'We are reseller service , we are not the file sharing service, so we cant provide you the exact reason. You should contact to file sharing to get your reason.', 'premium account banned, premium account locked, not login premium account, buypremiumkey reseller, buypremiumkey', '2018-05-19 07:22:08', '2018-10-08 04:09:26', 1, 233, 0),
(5, 'How will my bonus be used?', 'how-will-my-bonus-be-used', '<p>If you accumulate a large amount of bonuses from us, you can use [BONUS MONEY] payment method to buy <strong>premium key, premium account</strong> from buypremiumkey reseller.<br />\r\nEspecially with this payment method, you do not have to pay any extra fees. <strong>Charges is 0%</strong></p>\r\n\r\n<p><strong><img alt=\"Bonus premium key | buypremiumkey reseller\" src=\"http://buypremiumkey.com/images/news/1526728820.png\" style=\"width:100%\" /></strong></p>\r\n\r\n<p>In addition, you can still use your bonus money in other payment methods.&nbsp;As pictured below</p>\r\n\r\n<p><img alt=\"Buy premium key, premium account, voucher at buypremiumkey reseller\" src=\"http://buypremiumkey.com/images/news/1526729302.png\" style=\"width:100%\" /></p>\r\n\r\n<p><strong>TOTAL PRICE = SUB-TOTAL + CHARGES - MY BONUS</strong></p>\r\n\r\n<p><strong>To get the bonus money from us please read the article below:&nbsp;<a href=\"http://buypremiumkey.com/news/view-2/get-2-bonus-of-the-value-of-your-order-when-buying-any-premium-key-at-buypremiumkey-reseller.html\">&nbsp;http://buypremiumkey.com/news/view-2/get-2-bonus-of-the-value-of-your-order-when-buying-any-premium-key-at-buypremiumkey-reseller.html</a></strong></p>\r\n', 'How will my bonus be used | Buypremiumkey.Com Official Reseller', 'If you accumulate a large amount of bonuses from us, you can use [BONUS MONEY] payment method to buy premium key, premium account from buypremiumkey reseller.', 'bonus when buy key, bonus when buy premium, bonus premium, premium key free, premium account free, voucher free', '2018-05-19 11:38:59', '2018-10-08 00:01:38', 1, 197, 0),
(6, 'How to activate Katfile Premium Key at KatFile.Com', 'how-to-activate-katfile-premium-key-at-katfilecom', '<h2><strong>How to activate Katfile Premium Code / Voucher/ Pin Code:</strong></h2>\r\n\r\n<p><strong>After you get the KatFile Premium Key&nbsp;from Buypremiumkey.com reseller, you follow these steps to activate the KatFile Premium Key</strong></p>\r\n\r\n<ol>\r\n	<li>Create new user or login into your account at&nbsp;<a href=\"http://Katfile.Com\">Katfile.Com</a></li>\r\n	<li>Access this link : <a href=\"http://www.katfile.com/?op=my_account \">http://www.katfile.com/?op=my_account&nbsp;</a></li>\r\n	<li>You will see the form Apply Your Premium Key -&gt; Add the code and&nbsp;Apply</li>\r\n</ol>\r\n\r\n<p><em>Thank you for using buypremiumkey.com reseller service</em></p>\r\n\r\n<p><em>Have a nice day</em></p>\r\n', 'How to activate Katfile Premium Key at KatFile.Com | BuyPremiumKey.Com', 'BuyPremiumKey is official reseller of KatFile.Com premium key. You can buy KatFile premium key/account, voucher, coupon プレミアムキー  via Paypal, Visa/Master Card.', 'KatFile premium account, KatFile reseller paypal, KatFile reseller, KatFile key, KatFile account, KatFile premium, key KatFile, link generator KatFile, link KatFile premium, premium, premium account, active KatFile, how to active KatFile, KatFile active, KatFile free, KatFile bonus, KatFile voucher, KatFile coupon', '2018-05-20 10:39:22', '2018-10-08 02:04:39', 2, 257, 45),
(7, 'How to activate Filenext Premium Key/Account/Voucher/Coupon?', 'how-to-activate-filenext-premium-keyaccountvouchercoupon', '<h2>How to activate&nbsp;filenext premium key, please follow instruction:</h2>\r\n\r\n<p><strong>After you get the Filenex Premium Key&nbsp;from Buypremiumkey.com reseller, please&nbsp;follow these steps to activate the Filenex Premium Key:</strong></p>\r\n\r\n<ol>\r\n	<li>First, you have to Create new user or login&nbsp;your account at <a href=\"https://www.filenext.com/login.html\" target=\"_blank\">https://www.filenext.com/login.html</a></li>\r\n	<li>Then open this link: <a href=\"https://www.filenext.com/?op=my_account\" target=\"_blank\">https://www.filenext.com/?op=my_account</a></li>\r\n	<li>You will see the form&nbsp; --&gt;&nbsp;Enter your premium key and Apply.</li>\r\n</ol>\r\n\r\n<p><em>Thank you for using the service of <a href=\"http://buypremiumkey.com\">buypremiumkey.com</a> reseller!</em></p>\r\n\r\n<p><em>Have a nice day</em></p>\r\n', 'How to activate Filenext Premium Key at Filenext.com|Buypremiumkey.Com', 'BuyPremiumKey is official reseller of Filenext.Com premium key. You can buy Filenext premium key/account, voucher, coupon プレミアムキー  via Paypal, Visa/Master Card', 'Filenext premium account, Filenext reseller paypal, Filenext reseller, Filenext key, Filenext account, Filenext premium, key Filenext, link generator Filenext, link Filenext premium, premium, premium account, active Filenext, how to active Filenext, Filenext active, Filenext free, Filenext bonus, Filenext voucher, Filenext coupon', '2018-05-21 15:44:32', '2018-10-07 03:23:29', 2, 193, 44),
